mapper.insert:
INSERT INTO INQUIRY (
    INQUIRY_NO, MEMBER_NO, CATEGORY, TITLE, CONTENT
) VALUES (
    SEQ_INQUIRY_NO.NEXTVAL,
    #{memberNo}, #{category}, #{title}, #{content}
)

mapper.select:
SELECT * FROM ( SELECT I.INQUIRY_NO, I.MEMBER_NO, I.CATEGORY, I.TITLE, I.STATUS, TO_CHAR(I.CREATED_AT, 'YYYY-MM-DD HH24:MI') AS CREATED_AT, TO_CHAR(I.ANSWERED_AT, 'YYYY-MM-DD HH24:MI') AS ANSWERED_AT, M.NICKNAME AS MEMBER_NICKNAME, M.EMAIL AS MEMBER_EMAIL, ROW_NUMBER() OVER ( ORDER BY CASE WHEN I.STATUS = 'W' THEN 0 ELSE 1 END, I.CREATED_AT DESC ) AS RN FROM INQUIRY I JOIN MEMBER M ON I.MEMBER_NO = M.MEMBER_NO WHERE I.STATUS != 'D'
AND I.STATUS = #{status}
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE INQUIRY
SET STATUS = 'D'
WHERE INQUIRY_NO = #{inquiryNo}
